1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import bcrypt from "bcryptjs";
6	import { z } from "zod";
7	import { db } from "./db";
8	import { requireUser, requireAdmin, setImpersonation, clearImpersonation } from "./auth";
9	
10	// ---------- Profile ----------
11	
12	export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
13	  const user = await requireUser();
14	  const name = String(formData.get("name") ?? "").trim();
15	  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
16	  await db.user.update({ where: { id: user.id }, data: { name } });
17	  revalidatePath("/dashboard/settings");
18	  return { ok: true };
19	}
20	
21	export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
22	  const user = await requireUser();
23	  const current = String(formData.get("current") ?? "");
24	  const next = String(formData.get("next") ?? "");
25	  if (next.length < 8) return { error: "New password must be at least 8 characters." };
26	  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
27	  await db.user.update({
28	    where: { id: user.id },
29	    data: { passwordHash: await bcrypt.hash(next, 12) },
30	  });
31	  return { ok: true };
32	}
33	
34	// ---------- SSH keys ----------
35	
36	export async function addSshKey(prev: any, formData: FormData): Promise<{ error?: string }> {
37	  const user = await requireUser();
38	  const parsed = z
39	    .object({
40	      name: z.string().min(1).max(60),
41	      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
42	    })
43	    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
44	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
45	  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
46	  revalidatePath("/dashboard/settings");
47	  return {};
48	}
49	
50	export async function deleteSshKey(keyId: string) {
51	  const user = await requireUser();
52	  await db.sshKey.deleteMany({ where: { id: keyId, userId: user.id } });
53	  revalidatePath("/dashboard/settings");
54	}
55	
56	// ---------- Projects ----------
57	
58	export async function createProject(prev: any, formData: FormData): Promise<{ error?: string }> {
59	  const user = await requireUser();
60	  const name = String(formData.get("name") ?? "").trim();
61	  const color = String(formData.get("color") ?? "#6f47f5");
62	  if (name.length < 1 || name.length > 50) return { error: "Project name: 1–50 characters." };
63	  await db.project.create({ data: { userId: user.id, name, color } });
64	  revalidatePath("/dashboard/projects");
65	  return {};
66	}
67	
68	export async function deleteProject(projectId: string) {
69	  const user = await requireUser();
70	  await db.project.deleteMany({ where: { id: projectId, userId: user.id } });
71	  revalidatePath("/dashboard/projects");
72	}
73	
74	export async function assignServerProject(serverId: string, projectId: string | null) {
75	  const user = await requireUser();
76	  const server = await db.server.findUnique({ where: { id: serverId } });
77	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
78	  if (projectId) {
79	    const project = await db.project.findFirst({ where: { id: projectId, userId: server.userId } });
80	    if (!project) throw new Error("Project not found");
81	  }
82	  await db.server.update({ where: { id: serverId }, data: { projectId } });
83	  revalidatePath(`/dashboard/servers/${serverId}`);
84	}
85	
86	// ---------- Notifications ----------
87	
88	export async function markNotificationsRead() {
89	  const user = await requireUser();
90	  await db.notification.updateMany({
91	    where: { userId: user.id, readAt: null },
92	    data: { readAt: new Date() },
93	  });
94	  revalidatePath("/dashboard");
95	}
96	
97	// ---------- Password reset (email-based) ----------
98	
99	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
100	  const email = String(formData.get("email") ?? "").trim().toLowerCase();
101	  // Always report success (don't leak which emails exist)
102	  const user = await db.user.findUnique({ where: { email } });
103	  if (user) {
104	    const { randomBytes, createHash } = await import("node:crypto");
105	    const token = randomBytes(32).toString("base64url");
106	    const tokenHash = createHash("sha256").update(token).digest("hex");
107	    await db.passwordResetToken.create({
108	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
109	    });
110	    const { sendMail, emails } = await import("./mailer");
111	    const link = `${process.env.APP_URL ?? "https://revsports.ca"}/reset-password?token=${token}`;
112	    const tpl = emails.passwordReset(link);
113	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
114	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
115	  }
116	  return { sent: true };
117	}
118	
119	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
120	  const token = String(formData.get("token") ?? "");
121	  const password = String(formData.get("password") ?? "");
122	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
123	  const { createHash } = await import("node:crypto");
124	  const tokenHash = createHash("sha256").update(token).digest("hex");
125	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
126	  if (!row || row.usedAt || row.expiresAt < new Date()) {
127	    return { error: "This reset link is invalid or has expired. Request a new one." };
128	  }
129	  await db.$transaction([
130	    db.user.update({ where: { id: row.userId }, data: { passwordHash: await bcrypt.hash(password, 12) } }),
131	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
132	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
133	  ]);
134	  return { ok: true };
135	}
136	
137	/** Admin-triggered reset: emails the client a reset link. */
138	export async function adminSendPasswordReset(userId: string) {
139	  const admin = await requireAdmin();
140	  const user = await db.user.findUnique({ where: { id: userId } });
141	  if (!user) throw new Error("User not found");
142	  const { randomBytes, createHash } = await import("node:crypto");
143	  const token = randomBytes(32).toString("base64url");
144	  const tokenHash = createHash("sha256").update(token).digest("hex");
145	  await db.passwordResetToken.create({
146	    data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
147	  });
148	  const { sendMail, emails } = await import("./mailer");
149	  const link = `${process.env.APP_URL ?? "https://revsports.ca"}/reset-password?token=${token}`;
150	  const tpl = emails.passwordReset(link);
151	  await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
152	  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
153	}
154	
155	// ---------- Impersonation (admin) ----------
156	
157	export async function impersonateUser(userId: string) {
158	  const admin = await requireAdmin();
159	  const target = await db.user.findUnique({ where: { id: userId } });
160	  if (!target || target.role === "ADMIN") throw new Error("Cannot impersonate this account");
161	  await setImpersonation(userId);
162	  await db.auditLog.create({
163	    data: { userId: admin.id, action: "admin.impersonate_start", detail: `${target.email}` },
164	  });
165	  redirect("/dashboard");
166	}
167	
168	export async function stopImpersonating() {
169	  await clearImpersonation();
170	  redirect("/admin/users");
171	}
