90	export function StatusDot({ status, label }: { status: string; label?: string }) {
91	  const s = statusColors[status] ?? statusColors.STOPPED;
92	  return (
93	    <span className={`inline-flex items-center gap-2 text-xs font-medium ${s.text}`}>
94	      <span className={`h-2 w-2 rounded-full ${s.dot} ${s.pulse ? "animate-pulse-dot" : ""}`} />
95	      {(label ?? status).toLowerCase().replace(/_/g, " ")}
96	    </span>
97	  );
98	}
