import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";

/**
 * Dependency-free TOTP (RFC 6238) using only node:crypto.
 * - HMAC-SHA1 over a 30-second time counter
 * - 6-digit codes, verified with a ±1 step window
 * This is a plain module (no "use server"): it exports pure helpers.
 */

const BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
const DIGITS = 6;
const STEP_SECONDS = 30;

/** Encode raw bytes to an (unpadded) RFC 4648 base32 string. */
function base32Encode(buf: Buffer): string {
  let bits = 0;
  let value = 0;
  let out = "";
  for (const byte of buf) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      out += BASE32_ALPHABET[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) {
    out += BASE32_ALPHABET[(value << (5 - bits)) & 31];
  }
  return out;
}

/** Decode a base32 string (case-insensitive, ignores spaces/padding) to bytes. */
export function base32Decode(input: string): Buffer {
  const clean = input.toUpperCase().replace(/[\s=]/g, "");
  let bits = 0;
  let value = 0;
  const bytes: number[] = [];
  for (const char of clean) {
    const idx = BASE32_ALPHABET.indexOf(char);
    if (idx === -1) continue; // skip invalid chars defensively
    value = (value << 5) | idx;
    bits += 5;
    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
}

/** Generate a new base32 TOTP secret (default 20 bytes = 160 bits). */
export function generateSecret(bytes = 20): string {
  return base32Encode(randomBytes(bytes));
}

/** Compute the HMAC-SHA1 dynamic-truncation code for a specific counter. */
function hotp(secret: string, counter: number): string {
  const key = base32Decode(secret);
  const buf = Buffer.alloc(8);
  // 64-bit big-endian counter (JS-safe: high 32 bits then low 32 bits)
  buf.writeUInt32BE(Math.floor(counter / 0x100000000), 0);
  buf.writeUInt32BE(counter >>> 0, 4);
  const hmac = createHmac("sha1", key).update(buf).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const bin =
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff);
  return (bin % 10 ** DIGITS).toString().padStart(DIGITS, "0");
}

/** Current TOTP code (for the given time, default now). */
export function generateTOTP(secret: string, atMs: number = Date.now()): string {
  return hotp(secret, Math.floor(atMs / 1000 / STEP_SECONDS));
}

/**
 * Verify a submitted code against the secret with a ±1 step window
 * (tolerates minor clock drift). Constant-time comparison per step.
 */
export function verifyTOTP(secret: string, code: string, atMs: number = Date.now()): boolean {
  const cleaned = (code ?? "").replace(/\s/g, "");
  if (!/^\d{6}$/.test(cleaned)) return false;
  const counter = Math.floor(atMs / 1000 / STEP_SECONDS);
  for (let w = -1; w <= 1; w++) {
    const expected = hotp(secret, counter + w);
    const a = Buffer.from(expected);
    const b = Buffer.from(cleaned);
    if (a.length === b.length && timingSafeEqual(a, b)) return true;
  }
  return false;
}

/** Build an otpauth:// URI that authenticator apps can import (also render as QR). */
export function otpauthURL(secret: string, label: string, issuer = "Nxeon"): string {
  const enc = encodeURIComponent;
  const account = `${enc(issuer)}:${enc(label)}`;
  const params = new URLSearchParams({
    secret,
    issuer,
    algorithm: "SHA1",
    digits: String(DIGITS),
    period: String(STEP_SECONDS),
  });
  return `otpauth://totp/${account}?${params.toString()}`;
}

import { z } from "zod";

/**
 * Boot-time validation of critical environment variables.
 *
 * IMPORTANT: This never throws at import time — a missing var must not break
 * the build or crash a server component render. Instead `validateEnv()` returns
 * a structured result and logs a single clear warning listing what's missing.
 */

const envSchema = z.object({
  DATABASE_URL: z.string().min(1),
  AUTH_SECRET: z.string().min(1),
  PROXMOX_API_URL: z.string().min(1),
  PROXMOX_NODE: z.string().min(1),
  PROXMOX_TOKEN_ID: z.string().min(1),
  PROXMOX_TOKEN_SECRET: z.string().min(1),
});

export type EnvValidation = { ok: boolean; missing: string[] };

/**
 * Check that all critical env vars are present and non-empty.
 * Returns `{ ok, missing[] }` and logs a warning (never throws).
 */
export function validateEnv(): EnvValidation {
  const result = envSchema.safeParse(process.env);
  if (result.success) {
    return { ok: true, missing: [] };
  }
  // Collect the top-level keys that failed (missing or empty).
  const missing = Array.from(
    new Set(result.error.issues.map((i) => String(i.path[0])).filter(Boolean)),
  );
  console.warn(
    `[env] Missing or invalid critical environment variables: ${missing.join(", ")}. ` +
      `The app will continue to boot, but features depending on these will fail at runtime.`,
  );
  return { ok: false, missing };
}

/**
 * Dependency-free, in-memory sliding-window rate limiter.
 *
 * Suitable for single-process app-level throttling (login attempts, etc).
 * State lives in a module-level Map; on a horizontally-scaled deployment each
 * instance limits independently — acceptable for auth-abuse mitigation. A
 * background sweep prunes empty buckets so the Map does not grow unbounded.
 */

type Bucket = number[]; // sorted-ish list of hit timestamps (ms)

const buckets = new Map<string, Bucket>();

// Persist the Map across HMR / route reloads in dev.
const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;

export type RateLimitOptions = { max: number; windowMs: number };
export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };

/**
 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
 * When `ok` is false the caller should reject and surface `retryAfterSec`.
 */
export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
  const now = Date.now();
  const cutoff = now - windowMs;
  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);

  if (hits.length >= max) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
    store.set(key, hits); // persist the pruned window
    return { ok: false, retryAfterSec, remaining: 0 };
  }

  hits.push(now);
  store.set(key, hits);
  return { ok: true, retryAfterSec: 0, remaining: max - hits.length };
}

/** Clear the window for a key (e.g. after a successful login). */
export function resetRateLimit(key: string): void {
  store.delete(key);
}

/**
 * Preset for login throttling: 5 attempts per 15 minutes per identifier.
 * Pass a stable identifier such as `${email}:${ip}`.
 */
export function loginRateLimit(identifier: string): RateLimitResult {
  return checkRateLimit(`login:${identifier}`, { max: 5, windowMs: 15 * 60 * 1000 });
}

// Opportunistic sweep of fully-expired buckets (runs at most once/min).
let lastSweep = 0;
function sweep() {
  const now = Date.now();
  if (now - lastSweep < 60_000) return;
  lastSweep = now;
  const maxWindow = 15 * 60 * 1000;
  for (const [key, hits] of store) {
    if (hits.length === 0 || hits[hits.length - 1] < now - maxWindow) store.delete(key);
  }
}
// Piggyback the sweep on each check without a timer (edge/serverless-safe).
const _origCheck = checkRateLimit;
export function _sweepNow() {
  sweep();
}
void _origCheck;

