import { createHash } from "node:crypto";
import { db } from "./db";
import type { User } from "@prisma/client";

/**
 * Bearer-token authentication for the public REST API (`/api/v1/*`).
 *
 * Tokens are formatted `nxe_<prefix>_<random>` and only their sha256 hash is
 * stored (never the plaintext). Given an incoming request, resolve the bearer
 * token to its owning user, honouring `revoked` and `expiresAt`, and stamp
 * `lastUsedAt`.
 */

export const TOKEN_PREFIX = "nxe";

/** Extract the raw bearer token from an `Authorization: Bearer …` header. */
export function extractBearer(req: Request): string | null {
  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
  if (!header) return null;
  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/** sha256 hex hash of a token — the value stored in `ApiToken.tokenHash`. */
export function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

export type ApiAuthResult =
  | { ok: true; user: User; tokenId: string; scopes: string[] }
  | { ok: false; status: number; error: string };

/**
 * Authenticate an API request by its bearer token.
 * Returns the resolved user + token scopes, or a structured error with an
 * appropriate HTTP status for the route to return.
 */
export async function authenticateApiToken(req: Request): Promise<ApiAuthResult> {
  const raw = extractBearer(req);
  if (!raw) return { ok: false, status: 401, error: "Missing bearer token" };
  if (!raw.startsWith(`${TOKEN_PREFIX}_`)) {
    return { ok: false, status: 401, error: "Invalid token format" };
  }

  const tokenHash = hashToken(raw);
  const token = await db.apiToken.findUnique({
    where: { tokenHash },
    include: { user: true },
  });

  if (!token) return { ok: false, status: 401, error: "Invalid token" };
  if (token.revoked) return { ok: false, status: 401, error: "Token has been revoked" };
  if (token.expiresAt && token.expiresAt < new Date()) {
    return { ok: false, status: 401, error: "Token has expired" };
  }
  if (!token.user || token.user.suspended) {
    return { ok: false, status: 403, error: "Account unavailable" };
  }

  // Best-effort lastUsedAt stamp — never block the request on this write.
  db.apiToken
    .update({ where: { id: token.id }, data: { lastUsedAt: new Date() } })
    .catch(() => {});

  return { ok: true, user: token.user, tokenId: token.id, scopes: token.scopes };
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { authenticateApiToken } from "@/lib/api-auth";

export const dynamic = "force-dynamic";

/**
 * GET /api/v1/servers
 * Bearer-token authenticated. Returns the caller's servers.
 *
 *   Authorization: Bearer nxe_<prefix>_<random>
 */
export async function GET(req: Request) {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  const servers = await db.server.findMany({
    where: { userId: auth.user.id },
    orderBy: { createdAt: "desc" },
    select: { id: true, name: true, status: true, ipAddress: true },
  });

  return NextResponse.json({
    servers: servers.map((s) => ({
      id: s.id,
      name: s.name,
      status: s.status,
      ip: s.ipAddress,
    })),
  });
}

"use server";

import { revalidatePath } from "next/cache";
import { createHash, randomBytes } from "node:crypto";
import bcrypt from "bcryptjs";
import { db } from "./db";
import { requireUser } from "./auth";
import { generateSecret, otpauthURL, verifyTOTP } from "./totp";

/**
 * Two-factor authentication (TOTP) server actions.
 *
 * Enrolment flow:
 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
 *      stays false), and returns the otpauth URI + secret for the UI to show.
 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
 *      success `totpEnabled` flips true and backup codes are generated.
 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
 *      the account password.
 *
 * Backup codes are one-time; only their sha256 hashes are stored.
 */

function hashCode(code: string): string {
  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
}

/** Generate N human-friendly one-time backup codes (plaintext, for display). */
function makeBackupCodes(n = 10): string[] {
  return Array.from({ length: n }, () => {
    const raw = randomBytes(5).toString("hex"); // 10 hex chars
    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
  });
}

/**
 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
 * valid one-time backup code (which is then removed). Intended to be called by
 * the login flow once the password check succeeds.
 */
export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || !user.totpEnabled || !user.totpSecret) return false;

  if (verifyTOTP(user.totpSecret, code)) return true;

  // Fall back to consuming a backup code.
  const submitted = hashCode(code);
  const idx = user.backupCodes.indexOf(submitted);
  if (idx === -1) return false;
  const remaining = user.backupCodes.filter((_, i) => i !== idx);
  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
  return true;
}

/** Step 1: create (but do not yet activate) a TOTP secret. */
export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string }> {
  const user = await requireUser();
  const secret = generateSecret();
  await db.user.update({
    where: { id: user.id },
    data: { totpSecret: secret, totpEnabled: false },
  });
  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
}

/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
export async function confirmTotpEnrollment(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  if (!user.totpSecret) return { error: "Start enrolment first." };
  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect. Try again." };

  const backupCodes = makeBackupCodes();
  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true, backupCodes };
}

/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
export async function regenerateBackupCodes(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  if (!user.totpEnabled || !user.totpSecret) return { error: "2FA is not enabled." };
  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect." };
  const backupCodes = makeBackupCodes();
  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
  return { backupCodes };
}

/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
export async function disableTotp(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const proof = String(formData.get("proof") ?? "");
  if (!user.totpEnabled) return { error: "2FA is not enabled." };

  const codeValid =
    (user.totpSecret ? verifyTOTP(user.totpSecret, proof) : false) ||
    (await verifyTotpForUser(user.id, proof));
  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
  if (!codeValid && !passwordValid) {
    return { error: "Enter a valid authenticator code, backup code, or your password." };
  }

  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: false, totpSecret: null, backupCodes: [] },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

"use server";

import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { db } from "./db";
import { requireUser } from "./auth";
import { hashToken, TOKEN_PREFIX } from "./api-auth";

/**
 * Customer API-token server actions.
 *
 * Tokens are `nxe_<prefix>_<random>`. Only the sha256 hash + short prefix are
 * persisted; the full token is shown exactly once at creation time.
 */

const VALID_SCOPES = ["read", "write"] as const;

/** Create a token. Returns the plaintext ONCE — it is never retrievable again. */
export async function createApiToken(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; token?: string; name?: string }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 60) return { error: "Token name: 1–60 characters." };

  const scopesRaw = formData.getAll("scopes").map(String);
  const scopes = scopesRaw.filter((s): s is (typeof VALID_SCOPES)[number] =>
    (VALID_SCOPES as readonly string[]).includes(s),
  );
  if (scopes.length === 0) scopes.push("read");

  // Optional expiry in days.
  const expiresDays = Number(formData.get("expiresDays") ?? "");
  let expiresAt: Date | null = null;
  if (Number.isFinite(expiresDays) && expiresDays > 0) {
    expiresAt = new Date(Date.now() + expiresDays * 24 * 60 * 60 * 1000);
  }

  const prefix = randomBytes(4).toString("hex"); // 8-char public prefix
  const secret = randomBytes(24).toString("base64url");
  const fullToken = `${TOKEN_PREFIX}_${prefix}_${secret}`;

  await db.apiToken.create({
    data: {
      userId: user.id,
      name,
      prefix,
      tokenHash: hashToken(fullToken),
      scopes,
      expiresAt,
    },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_created", detail: name } });
  revalidatePath("/dashboard/settings");
  return { token: fullToken, name };
}

/** Revoke a token owned by the current user. */
export async function revokeApiToken(tokenId: string): Promise<void> {
  const user = await requireUser();
  await db.apiToken.updateMany({
    where: { id: tokenId, userId: user.id },
    data: { revoked: true },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.api_token_revoked" } });
  revalidatePath("/dashboard/settings");
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";

/**
 * Notification-preference server actions.
 *
 * Persisted to `User.notificationPrefs` (Json). Three toggle groups:
 *   - email:    transactional/account email (invoices, deploys)
 *   - product:  product news & announcements
 *   - security: security alerts (new logins, token changes)
 */

export type NotificationPrefs = {
  email: boolean;
  product: boolean;
  security: boolean;
};

export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };

/** Normalise whatever is stored in the Json column into a typed prefs object. */
export function normalizePrefs(raw: unknown): NotificationPrefs {
  const p = (raw ?? {}) as Record<string, unknown>;
  return {
    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    security: typeof p.security === "boolean" ? p.security : DEFAULT_PREFS.security,
  };
}

/** Save notification preferences from the settings form. */
export async function updateNotificationPrefs(
  prev: unknown,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const prefs: NotificationPrefs = {
    email: formData.get("email") === "on",
    product: formData.get("product") === "on",
    security: formData.get("security") === "on",
  };
  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

