"use client";

import { useActionState, useState, useTransition } from "react";
import { Badge, timeAgo } from "@/components/ui/primitives";
import {
  beginTotpEnrollment,
  confirmTotpEnrollment,
  disableTotp,
  regenerateBackupCodes,
} from "@/lib/actions-2fa";
import { createApiToken, revokeApiToken } from "@/lib/actions-tokens";

export type TokenView = {
  id: string;
  name: string;
  prefix: string;
  scopes: string[];
  lastUsedAt: Date | null;
  expiresAt: Date | null;
  revoked: boolean;
  createdAt: Date;
};

/* ------------------------------- Backup codes ------------------------------ */

function BackupCodes({ codes }: { codes: string[] }) {
  return (
    <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.06] p-4">
      <p className="mb-2 text-sm font-medium text-amber-300">Save your backup codes</p>
      <p className="mb-3 text-xs text-slate-400">
        Each code works once. Store them somewhere safe — they are shown only now and let you sign in
        if you lose your authenticator.
      </p>
      <div className="grid grid-cols-2 gap-2 font-mono text-sm sm:grid-cols-2">
        {codes.map((c) => (
          <span key={c} className="rounded-lg border border-white/10 bg-white/[0.03] px-3 py-1.5">
            {c}
          </span>
        ))}
      </div>
    </div>
  );
}

/* ----------------------------------- 2FA ----------------------------------- */

function TwoFactorSection({ enabled }: { enabled: boolean }) {
  const [starting, startBegin] = useTransition();
  const [enrollment, setEnrollment] = useState<{ secret: string; otpauthUrl: string } | null>(null);

  const [confirmState, confirmAction, confirming] = useActionState(confirmTotpEnrollment, {});
  const [disableState, disableAction, disabling] = useActionState(disableTotp, {});
  const [regenState, regenAction, regenerating] = useActionState(regenerateBackupCodes, {});

  // Enabled + confirmed enrolment complete -> backup codes may be present.
  const freshBackupCodes = confirmState?.backupCodes ?? regenState?.backupCodes;

  if (enabled) {
    return (
      <div className="space-y-5">
        <div className="flex items-center gap-3">
          <Badge tone="green">enabled</Badge>
          <span className="text-sm text-slate-400">
            Two-factor authentication is protecting your account.
          </span>
        </div>

        {freshBackupCodes && <BackupCodes codes={freshBackupCodes} />}

        <div className="grid gap-6 sm:grid-cols-2">
          <form action={regenAction} className="space-y-3">
            <p className="text-sm font-medium">Regenerate backup codes</p>
            <input
              className="input"
              name="code"
              inputMode="numeric"
              placeholder="Authenticator code"
              autoComplete="one-time-code"
            />
            <button className="btn-secondary" disabled={regenerating}>
              {regenerating ? "Generating…" : "Regenerate codes"}
            </button>
            {regenState?.error && <p className="text-sm text-red-400">{regenState.error}</p>}
          </form>

          <form action={disableAction} className="space-y-3">
            <p className="text-sm font-medium">Disable 2FA</p>
            <input
              className="input"
              name="proof"
              placeholder="Code or account password"
              autoComplete="off"
            />
            <button className="btn-danger" disabled={disabling}>
              {disabling ? "Disabling…" : "Disable 2FA"}
            </button>
            {disableState?.error && <p className="text-sm text-red-400">{disableState.error}</p>}
          </form>
        </div>
      </div>
    );
  }

  // Not enabled.
  return (
    <div className="space-y-5">
      <div className="flex items-center gap-3">
        <Badge tone="slate">disabled</Badge>
        <span className="text-sm text-slate-400">
          Add a second step at sign-in using an authenticator app.
        </span>
      </div>

      {!enrollment ? (
        <button
          className="btn-primary"
          disabled={starting}
          onClick={() => startBegin(async () => setEnrollment(await beginTotpEnrollment()))}
        >
          {starting ? "Preparing…" : "Set up 2FA"}
        </button>
      ) : (
        <div className="space-y-4">
          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
            <p className="mb-2 text-sm">
              1. Add this account to your authenticator app (Google Authenticator, 1Password, Authy…).
            </p>
            <p className="mb-1 text-xs text-slate-500">Scan / open this URI:</p>
            <code className="block break-all rounded-lg border border-white/10 bg-black/30 px-3 py-2 font-mono text-xs text-brand-300">
              {enrollment.otpauthUrl}
            </code>
            <p className="mb-1 mt-3 text-xs text-slate-500">Or enter this secret manually:</p>
            <code className="block break-all rounded-lg border border-white/10 bg-black/30 px-3 py-2 font-mono text-sm">
              {enrollment.secret}
            </code>
          </div>

          <form action={confirmAction} className="space-y-3">
            <p className="text-sm">2. Enter the 6-digit code from your app to confirm.</p>
            <div className="flex items-center gap-3">
              <input
                className="input max-w-40"
                name="code"
                inputMode="numeric"
                placeholder="123456"
                autoComplete="one-time-code"
                required
              />
              <button className="btn-primary" disabled={confirming}>
                {confirming ? "Verifying…" : "Confirm & enable"}
              </button>
            </div>
            {confirmState?.error && <p className="text-sm text-red-400">{confirmState.error}</p>}
          </form>
        </div>
      )}
    </div>
  );
}

/* -------------------------------- API tokens ------------------------------- */

function CreateTokenForm() {
  const [state, action, pending] = useActionState(createApiToken, {});
  return (
    <div className="space-y-4">
      {state?.token && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/[0.06] p-4">
          <p className="mb-2 text-sm font-medium text-emerald-300">
            Token created — copy it now, it won&apos;t be shown again.
          </p>
          <code className="block break-all rounded-lg border border-white/10 bg-black/30 px-3 py-2 font-mono text-sm">
            {state.token}
          </code>
        </div>
      )}
      <form action={action} className="space-y-4">
        {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
        <div className="grid gap-4 sm:grid-cols-3">
          <div className="sm:col-span-1">
            <label className="label">Token name</label>
            <input className="input" name="name" required maxLength={60} placeholder="ci-deploy" />
          </div>
          <div>
            <label className="label">Expires (days)</label>
            <input className="input" name="expiresDays" type="number" min={1} placeholder="never" />
          </div>
          <div>
            <label className="label">Scopes</label>
            <div className="flex items-center gap-4 pt-2 text-sm">
              <label className="flex items-center gap-1.5">
                <input type="checkbox" name="scopes" value="read" defaultChecked /> read
              </label>
              <label className="flex items-center gap-1.5">
                <input type="checkbox" name="scopes" value="write" /> write
              </label>
            </div>
          </div>
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Creating…" : "Create token"}
        </button>
      </form>
    </div>
  );
}

function RevokeTokenButton({ tokenId }: { tokenId: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-danger px-3 py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (window.confirm("Revoke this token? Any integration using it will stop working."))
          start(() => revokeApiToken(tokenId));
      }}
    >
      {pending ? "…" : "Revoke"}
    </button>
  );
}

function ApiTokensSection({ tokens }: { tokens: TokenView[] }) {
  return (
    <div className="space-y-6">
      {tokens.length > 0 && (
        <ul className="divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
          {tokens.map((t) => (
            <li key={t.id} className="flex items-center justify-between gap-4 px-4 py-3">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <p className="text-sm font-medium">{t.name}</p>
                  {t.revoked ? (
                    <Badge tone="red">revoked</Badge>
                  ) : t.expiresAt && t.expiresAt < new Date() ? (
                    <Badge tone="amber">expired</Badge>
                  ) : (
                    <Badge tone="slate">{t.scopes.join(", ") || "read"}</Badge>
                  )}
                </div>
                <p className="mt-0.5 font-mono text-xs text-slate-500">
                  nxe_{t.prefix}_••••••••
                </p>
              </div>
              <div className="flex shrink-0 items-center gap-3">
                <span className="hidden text-xs text-slate-500 sm:block">
                  {t.lastUsedAt ? `used ${timeAgo(t.lastUsedAt)}` : "never used"} · created{" "}
                  {timeAgo(t.createdAt)}
                  {t.expiresAt ? ` · expires ${t.expiresAt.toISOString().slice(0, 10)}` : ""}
                </span>
                {!t.revoked && <RevokeTokenButton tokenId={t.id} />}
              </div>
            </li>
          ))}
        </ul>
      )}
      <CreateTokenForm />
    </div>
  );
}

/* --------------------------------- Wrapper --------------------------------- */

export function SecuritySettings({
  totpEnabled,
  tokens,
}: {
  totpEnabled: boolean;
  tokens: TokenView[];
}) {
  return (
    <>
      <div className="card">
        <h2 className="mb-1 font-semibold">Two-factor authentication</h2>
        <p className="mb-5 text-sm text-slate-400">
          Protect your account with a time-based one-time code.
        </p>
        <TwoFactorSection enabled={totpEnabled} />
      </div>

      <div className="card">
        <div className="mb-1 flex items-center justify-between">
          <h2 className="font-semibold">API tokens</h2>
          <span className="text-xs text-slate-500">
            {tokens.filter((t) => !t.revoked).length} active
          </span>
        </div>
        <p className="mb-5 text-sm text-slate-400">
          Authenticate REST calls with{" "}
          <code className="font-mono text-xs text-brand-300">Authorization: Bearer nxe_…</code>. The
          full token is shown only once.
        </p>
        <ApiTokensSection tokens={tokens} />
      </div>
    </>
  );
}

